package solution

import (
	"bytes"
	"fmt"
	"go/ast"
	"go/format"
	"go/parser"
	"go/token"
)

type FieldMatch struct{ Destination, Source string }
type fieldInfo struct{ name, typ string }

func findStruct(src, name string) (*ast.StructType, error) {
	file, err := parser.ParseFile(token.NewFileSet(), "input.go", src, 0)
	if err != nil {
		return nil, err
	}
	for _, declaration := range file.Decls {
		group, ok := declaration.(*ast.GenDecl)
		if !ok {
			continue
		}
		for _, specification := range group.Specs {
			typeSpec, ok := specification.(*ast.TypeSpec)
			if !ok || typeSpec.Name.Name != name {
				continue
			}
			structure, ok := typeSpec.Type.(*ast.StructType)
			if !ok {
				return nil, fmt.Errorf("%s is not a struct", name)
			}
			return structure, nil
		}
	}
	return nil, fmt.Errorf("struct %s not found", name)
}

func rendered(expression ast.Expr) string {
	var buffer bytes.Buffer
	_ = format.Node(&buffer, token.NewFileSet(), expression)
	return buffer.String()
}

func eligible(name string) bool {
	return len(name) > 0 && name[0] >= 'A' && name[0] <= 'Z'
}

func asciiLower(name string) string {
	lower := []byte(name)
	for index, ch := range lower {
		if ch >= 'A' && ch <= 'Z' {
			lower[index] = ch + ('a' - 'A')
		}
	}
	return string(lower)
}

func InspectFieldMatches(destinationSource, destinationType, sourceSource, sourceType string) ([]FieldMatch, error) {
	destination, err := findStruct(destinationSource, destinationType)
	if err != nil {
		return nil, err
	}
	source, err := findStruct(sourceSource, sourceType)
	if err != nil {
		return nil, err
	}

	index := make(map[string][]fieldInfo)
	for _, field := range source.Fields.List {
		for _, name := range field.Names {
			if eligible(name.Name) {
				key := asciiLower(name.Name)
				index[key] = append(index[key], fieldInfo{name: name.Name, typ: rendered(field.Type)})
			}
		}
	}

	matches := make([]FieldMatch, 0)
	for _, field := range destination.Fields.List {
		fieldType := rendered(field.Type)
		for _, name := range field.Names {
			if !eligible(name.Name) {
				continue
			}
			candidates := index[asciiLower(name.Name)]
			if len(candidates) == 1 && candidates[0].typ == fieldType {
				matches = append(matches, FieldMatch{Destination: name.Name, Source: candidates[0].name})
			}
		}
	}
	return matches, nil
}
